// One Slack message listing new reviews at or under maxStars, grouped by app and store. Nothing to report: no message.
const max = Number($('Settings').first().json.maxStars ?? 3);
const reviews = $input.all().map((i) => i.json).filter((r) => r.found !== false && r.rating !== null && r.rating <= max);
if (reviews.length === 0) return [];
const storeName = { google_play: 'Google Play', app_store: 'App Store' };
const byApp = {};
for (const r of reviews) (byApp[`${r.appTitle ?? r.appId} (${storeName[r.store] ?? r.store}, ${r.searchCountry})`] ??= []).push(r);
const stars = (n) => '★'.repeat(n) + '☆'.repeat(5 - n);
const blocks = Object.entries(byApp).map(([app, list]) => {
  const lines = list.slice(0, 10).map((r) => `• ${stars(r.rating)} ${r.title ? `*${r.title}* ` : ''}${(r.text ?? '').slice(0, 200)} (${(r.reviewedAt ?? '').slice(0, 10)}${r.appVersion ? `, v${r.appVersion}` : ''})`);
  if (list.length > 10) lines.push(`…and ${list.length - 10} more`);
  const url = list[0].appUrl ? ` <${list[0].appUrl}|open>` : '';
  return `*${app}*${url}: ${list.length} new review${list.length > 1 ? 's' : ''} at ${max} stars or less\n${lines.join('\n')}`;
});
return [{ json: { text: `:iphone: *New app reviews to answer*\n\n${blocks.join('\n\n')}`, newReviews: reviews.length } }];
